mapper.insert:
INSERT INTO file_mq_outbox (
    id, event_id, image_id, event_type, topic, tag, message_key, payload,
    schema_version, status, retry_count, max_retries, next_retry_time, version_id
)
VALUES (
    #{id}, #{eventId}, #{imageId}, #{eventType}, #{topic}, #{tag}, #{messageKey}, #{payload},
    #{schemaVersion}, #{status}, #{retryCount}, #{maxRetries}, #{nextRetryTime}, #{versionId}
)

mapper.update:
update file_mq_outbox set
    status = 'RETRY_WAIT', next_retry_time = TIMESTAMPADD(SECOND, #{retryDelaySeconds}, CURRENT_TIMESTAMP), retry_count = retry_count + 1,
    version_id = version_id + 1, update_time = current_timestamp, last_error = #{lastError}
where id = #{id} and status = 'SENDING' and version_id = #{expectedVersionId}
    and retry_count < max_retries and update_time < TIMESTAMPADD(SECOND, -#{timeoutSeconds}, CURRENT_TIMESTAMP)

update file_mq_outbox set
    status = 'DEAD', version_id = version_id + 1,
    update_time = current_timestamp, last_error = #{lastError}
where id = #{id} and status = 'SENDING' and version_id = #{expectedVersionId}
  and retry_count >= max_retries and update_time < TIMESTAMPADD(SECOND, -#{timeoutSeconds}, CURRENT_TIMESTAMP)

mapper.delete:
delete from file_mq_outbox
where status = 'SENT' and sent_time < TIMESTAMPADD(DAY, -#{sentRetentionDays}, CURRENT_TIMESTAMP)
    order by sent_time, id limit #{cleanBatchSize}
